sp_widget.client_script:
api.controller = function($timeout) {

  var c = this;

  c.loading = true;


  /*
   * The actual validation is performed by the
   * Check-In widget Server Script.
   *
   * Wait briefly so the server response is rendered
   * cleanly in the portal.
   */

  $timeout(function() {

    c.loading = false;

  }, 300);

};

sp_widget.css:
.campus360-checkin {
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px 20px;
  background: #f7f8fa;
  font-family: Arial, sans-serif;
}

.checkin-card {
  width: 100%;
  max-width: 560px;
  background: #ffffff;
  border: 1px solid #e2e6ed;
  border-radius: 16px;
  padding: 40px;
  text-align: center;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.07);
}

.eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.4px;
  color: #737b8c;
  margin-bottom: 10px;
}

.checkin-card h1 {
  margin: 0;
  font-size: 28px;
  color: #172033;
}

.checkin-card h2 {
  margin: 0 0 8px;
  color: #172033;
}

.checkin-card p {
  margin: 12px auto 0;
  color: #687184;
  line-height: 1.6;
}

.success-icon,
.info-icon,
.error-icon {
  width: 65px;
  height: 65px;
  border-radius: 50%;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  font-weight: 700;
}

.success-icon {
  background: #e9f8ef;
  color: #197044;
}

.info-icon {
  background: #eaf3ff;
  color: #1769aa;
}

.error-icon {
  background: #fff0f0;
  color: #b42318;
}

.checkin-details {
  margin-top: 28px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  text-align: left;
}

.checkin-details div {
  background: #f7f8fa;
  border-radius: 9px;
  padding: 14px;
}

.checkin-details span {
  display: block;
  font-size: 10px;
  color: #737b8c;
  margin-bottom: 5px;
}

.checkin-details strong {
  display: block;
  font-size: 14px;
  color: #172033;
  word-break: break-word;
}

.checkin-spinner {
  width: 35px;
  height: 35px;
  border: 3px solid #e5e7eb;
  border-top-color: #172033;
  border-radius: 50%;
  margin: 0 auto 18px;
  animation: checkinSpin 0.8s linear infinite;
}

@keyframes checkinSpin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 600px) {

  .checkin-card {
    padding: 30px 20px;
  }

  .checkin-details {
    grid-template-columns: 1fr;
  }

}

sp_widget.script:
(function() {

  /* =========================================================
     INITIAL RESPONSE
     ========================================================= */

  data.success = false;
  data.already_scanned = false;

  data.message =
    'The interview QR code is incomplete or invalid. Please ask the student to open the interview again and display a valid QR code.';

  data.interview_id = '';
  data.student = '';
  data.attendance_status = '';
  data.interview_status = '';


  /* =========================================================
     GET QR PARAMETERS
     ========================================================= */

  var interviewSysId =
    $sp.getParameter('interview');

  var token =
    $sp.getParameter('token');

  interviewSysId =
    String(interviewSysId || '').trim();

  token =
    String(token || '').trim();


  /* =========================================================
     VALIDATE PARAMETERS
     ========================================================= */

  if (!interviewSysId || !token) {
    return;
  }


  /* =========================================================
     LOAD MOCK INTERVIEW
     ========================================================= */

  var interviewGR =
    new GlideRecord(
      'x_snc_campus360_mock_interview'
    );

  if (!interviewGR.get(interviewSysId)) {

    data.message =
      'The interview linked to this QR code could not be found.';

    return;
  }


  /* =========================================================
     VERIFY QR TOKEN
     ========================================================= */

  var storedToken =
    String(
      interviewGR.getValue('qr_code') || ''
    ).trim();

  if (!storedToken || storedToken !== token) {

    data.message =
      'This QR code is not valid for this interview. Please generate a new QR code.';

    return;
  }


  /* =========================================================
     BASIC INFORMATION
     ========================================================= */

  data.interview_id =
    interviewGR.getDisplayValue(
      'interview_id'
    );

  data.student =
    interviewGR.getDisplayValue(
      'student'
    );

  data.attendance_status =
    interviewGR.getDisplayValue(
      'attendance_status'
    );

  data.interview_status =
    interviewGR.getDisplayValue(
      'interview_status'
    );


  /* =========================================================
     CHECK IF ALREADY SCANNED
     ========================================================= */

  var currentQRStatus =
    interviewGR.getDisplayValue(
      'qr_status'
    );

  var currentAttendance =
    interviewGR.getDisplayValue(
      'attendance_status'
    );


  if (
    String(currentQRStatus).toLowerCase() === 'scanned' ||
    String(currentAttendance).toLowerCase() === 'present'
  ) {

    data.already_scanned = true;

    data.success = false;

    data.message =
      'This interview has already been checked in.';

    return;
  }


  /* =========================================================
     VERIFY REQUIRED FIELDS
     ========================================================= */

  if (!interviewGR.isValidField('attendance_status')) {

    data.message =
      'The attendance_status field is missing from Mock Interview.';

    return;
  }

  if (!interviewGR.isValidField('qr_status')) {

    data.message =
      'The qr_status field is missing from Mock Interview.';

    return;
  }

  if (!interviewGR.isValidField('interview_status')) {

    data.message =
      'The interview_status field is missing from Mock Interview.';

    return;
  }


  /* =========================================================
     UPDATE ATTENDANCE STATUS

     IMPORTANT:
     Using setValue() because setDisplayValue()
     is not allowed in the x_snc_campus360 scope.
     ========================================================= */

  interviewGR.setValue(
    'attendance_status',
    'Present'
  );


  /* =========================================================
     UPDATE QR STATUS
     ========================================================= */

  interviewGR.setValue(
    'qr_status',
    'Scanned'
  );


  /* =========================================================
     UPDATE INTERVIEW STATUS
     ========================================================= */

  interviewGR.setValue(
    'interview_status',
    'In Progress'
  );


  /* =========================================================
     SAVE RECORD
     ========================================================= */

  var updatedSysId =
    interviewGR.update();


  if (!updatedSysId) {

    data.message =
      'The QR was valid, but ServiceNow could not update the interview. Check ACLs or Business Rules on Mock Interview.';

    return;
  }


  /* =========================================================
     SUCCESS
     ========================================================= */

  data.success = true;

  data.already_scanned = false;

  data.message =
    'Interview check-in completed successfully.';


  data.interview_id =
    interviewGR.getDisplayValue(
      'interview_id'
    );

  data.student =
    interviewGR.getDisplayValue(
      'student'
    );

  data.attendance_status =
    interviewGR.getDisplayValue(
      'attendance_status'
    );

  data.interview_status =
    interviewGR.getDisplayValue(
      'interview_status'
    );


})();
